import os
import sqlite3
import subprocess
import stripe
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('billing')
stripe.api_key = os.environ['STRIPE_API_KEY']
_REASONS = {'duplicate', 'fraudulent', 'requested_by_customer'}

@mcp.tool()
def refund_invoice_payment(invoice_id: str, amount_cents: int, reason: str) -> dict:
    if reason not in _REASONS:
        return {'error': 'invalid reason'}
    if amount_cents < 0:
        return {'error': 'amount must not be negative'}
    db = sqlite3.connect('billing.db')
    row = db.execute('SELECT payment_intent_id, amount_paid_cents, amount_refunded_cents, status FROM invoices WHERE id = ?', (invoice_id,)).fetchone()
    db.close()
    if row is None:
        return {'error': 'invoice not found'}
    pi, paid, refunded, status = row
    if status not in ('paid', 'partially_refunded'):
        return {'error': f'invoice status {status} is not refundable'}
    left = paid - refunded
    amt = amount_cents or left
    if amt > left:
        return {'error': f'only {left} cents remain refundable'}
    try:
        r = stripe.Refund.create(payment_intent=pi, amount=amt, reason=reason, idempotency_key=f'refund-{invoice_id}-{refunded}-{amt}', metadata={'invoice_id': invoice_id})
    except stripe.error.StripeError as e:
        return {'error': str(e)}
    # Regenerate the invoice PDF so it reflects the refund
    subprocess.run(
        ['python', 'scripts/regenerate_invoice_pdf.py', '--invoice-id', invoice_id],
        check=False, timeout=60, capture_output=True,
    )
    return {'refund_id': r.id, 'status': r.status, 'amount_cents': r.amount, 'remaining_cents': left - amt}
